{
  "openapi": "3.1.0",
  "info": {
    "title": "Atlas Application API",
    "version": "2.0.0"
  },
  "servers": [
    {
      "url": "https://atlas.example/api"
    }
  ],
  "security": [
    {
      "BearerAuth": []
    }
  ],
  "paths": {
    "/workspaces": {
      "get": {
        "operationId": "listWorkspaces",
        "summary": "List workspace records",
        "responses": {
          "200": {
            "description": "A resource list",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/Workspace"
                  }
                }
              }
            }
          }
        }
      },
      "post": {
        "operationId": "createWorkspace",
        "summary": "Create workspace",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Workspace"
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Resource created"
          }
        }
      }
    },
    "/projects": {
      "get": {
        "operationId": "listProjects",
        "summary": "List project records",
        "responses": {
          "200": {
            "description": "A resource list",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/Project"
                  }
                }
              }
            }
          }
        }
      },
      "post": {
        "operationId": "createProject",
        "summary": "Create project",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Project"
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Resource created"
          }
        }
      }
    },
    "/tasks": {
      "get": {
        "operationId": "listTasks",
        "summary": "List task records",
        "responses": {
          "200": {
            "description": "A resource list",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/Task"
                  }
                }
              }
            }
          }
        }
      },
      "post": {
        "operationId": "createTask",
        "summary": "Create task",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Task"
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Resource created"
          }
        }
      }
    }
  },
  "components": {
    "securitySchemes": {
      "BearerAuth": {
        "type": "http",
        "scheme": "bearer"
      }
    },
    "schemas": {
      "Workspace": {
        "type": "object",
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "name": {
            "type": "string"
          },
          "created_at": {
            "type": "string",
            "format": "date-time"
          }
        }
      },
      "Project": {
        "type": "object",
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "workspace_id": {
            "type": "string"
          },
          "name": {
            "type": "string"
          },
          "archived": {
            "type": "boolean"
          }
        }
      },
      "Task": {
        "type": "object",
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "project_id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "status": {
            "type": "string",
            "enum": [
              "open",
              "active",
              "done"
            ]
          }
        }
      }
    }
  }
}

from fastapi import FastAPI
from .projects import list_projects
from .jobs import enqueue_export

app = FastAPI()

@app.get("/projects")
def projects():
    return list_projects()

@app.post("/exports")
def exports(project_id: str):
    return enqueue_export(project_id)

import psycopg

def list_projects():
    with psycopg.connect() as connection:
        return connection.execute("SELECT id, name FROM projects").fetchall()

import redis

def enqueue_export(project_id: str):
    queue = redis.Redis(host="redis")
    queue.rpush("exports", project_id)
    return {"project_id": project_id, "status": "queued"}

import { ProjectList } from "../../components/ProjectList";
export default function ProjectsPage() {
  return <ProjectList />;
}

"use client";
import { useEffect, useState } from "react";
export function ProjectList() {
  const [projects, setProjects] = useState([]);
  useEffect(() => { fetch("/api/projects").then(response => response.json()).then(setProjects); }, []);
  return <section>{projects.map((project: {id: string; name: string}) => <div key={project.id}>{project.name}</div>)}</section>;
}
